local a=require("fcs.io.cfgspec")local b={}function b.plan(c)c=c or{}if c.hasDevbind and c.hasSenscal then return{action="already-split"}end;if type(c.fused)~="table"then return{action="abort",err="no readable fused config"}end;local d=a.splitLegacy(c.fused)local e={action="write"}if not c.hasDevbind then local f=a.merge("devbind",d.devbind)local g,h=a.validate("devbind",f)if not g then return{action="abort",err="devbind invalid: "..tostring(h)}end;e.devbind=f end;if not c.hasSenscal then local i=a.merge("senscal",d.senscal)local g,h=a.validate("senscal",i)if not g then return{action="abort",err="senscal invalid: "..tostring(h)}end;e.senscal=i end;return e end;local j=require("fcs.io.fsx")local k="/eh2_hw_config.tbl"local function l(m)return fs.exists(m)and not fs.isDir(m)end;function b.run(n)n=n or{}local o=n.read or j.read;local p=n.write or j.writeAtomic;local q=n.exists or l;local r=q("/"..a.FILES.devbind)local s=q("/"..a.FILES.senscal)local t=o(k)local u=t and textutils.unserialise(t)or nil;local v=b.plan({fused=u,hasDevbind=r,hasSenscal=s})if v.action=="already-split"then return"Already split -- eh2_devbind.tbl + eh2_senscal.tbl present. No change."end;if v.action=="abort"then return"ABORT: "..tostring(v.err).." (nothing written; fused file untouched)."end;local w={}if v.devbind then a.save("devbind",v.devbind,p)w[#w+1]=a.FILES.devbind end;if v.senscal then a.save("senscal",v.senscal,p)w[#w+1]=a.FILES.senscal end;if n.backup then for x,y in ipairs(w)do n.backup("/"..y)end end;return"Split OK -- wrote "..table.concat(w,", ").." (fused file left intact as fallback)."end;return b